<?php
namespace App\Jobs;use App\Mail\TestSmtpMail;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;use Illuminate\Support\Facades\Mail;
final class SendTestEmailJob implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public function __construct(public readonly array $payload){}public function handle():void{$mailer='v2_dynamic_'.substr(hash('sha256',$this->payload['smtp_host'].':'.$this->payload['smtp_port'].':'.$this->payload['sender_email']),0,12);config(["mail.mailers.$mailer"=>['transport'=>'smtp','scheme'=>$this->payload['smtp_port']===465?'smtps':null,'host'=>$this->payload['smtp_host'],'port'=>$this->payload['smtp_port'],'username'=>$this->payload['sender_email'],'password'=>$this->payload['sender_password'],'timeout'=>null,'local_domain'=>parse_url(config('app.url'),PHP_URL_HOST)]]);Mail::mailer($mailer)->to($this->payload['recipient_email'])->send((new TestSmtpMail($this->payload['subject'],$this->payload['body']))->from($this->payload['sender_email']));}}
